 export interface CircuitBreakerConfig {
   maxConsecutiveFailures: number;
   /** Ordered profile-name rotation, e.g. `["copilot", "agy", "claude"]`. */
   rotation: readonly string[];
   onExhausted: "fail";
   resetTimeoutMs: number;
 }

 /** Command/model settings for one translation provider profile. */
 export interface ProviderProfileConfig {
   /** Binary name, or a path resolved against the config directory when it contains a separator. */
   command: string;
   model: string;
   effort?: string;
   concurrency: number;
 }

 /** Translation provider endpoint, profiles, budget, and circuit-breaker settings. */
 export interface ProviderConfig {
   default: string;
   endpoint: string;
   batchBudget: number;
   timeoutMs: number;
   /** Timeout for a whole-document (`segment: "file"`) translation, which runs far longer than a
    *  batch of short strings. */
   documentTimeoutMs: number;
   circuitBreaker: CircuitBreakerConfig;
   profiles: Readonly<Record<string, ProviderProfileConfig>>;
 }

